import{_ as t,o as a,c as i,a9 as r}from"./chunks/framework.asyjyako.js";const p=JSON.parse('{"title":"Choose an interface","description":"","frontmatter":{},"headers":[],"relativePath":"interfaces/packages.md","filePath":"interfaces/packages.md","lastUpdated":null}'),n={name:"interfaces/packages.md"};function s(o,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="Choose-an-interface" tabindex="-1">Choose an interface <a class="header-anchor" href="#Choose-an-interface" aria-label="Permalink to &quot;Choose an interface {#Choose-an-interface}&quot;">​</a></h1><p>PerfChecker includes a Julia API, command-line entry point and terminal selector. Optional packages add a web interface, notebooks and plots. The VS Code extension runs individual items from the editor&#39;s Testing view.</p><table tabindex="0"><thead><tr><th style="text-align:right;">I want to…</th><th style="text-align:right;">Use</th><th style="text-align:right;">Try it with Bibliography</th></tr></thead><tbody><tr><td style="text-align:right;">Run an existing test individually while editing code</td><td style="text-align:right;"><a href="./vscode">VS Code</a></td><td style="text-align:right;">Discover the two example items and run only the export item</td></tr><tr><td style="text-align:right;">Select workloads and versions in a browser</td><td style="text-align:right;"><a href="./web-studio">Oxygen Web Studio</a></td><td style="text-align:right;">Select one export benchmark, then reopen its plot</td></tr><tr><td style="text-align:right;">Choose checks from a terminal</td><td style="text-align:right;"><a href="./repl-pluto">REPL</a></td><td style="text-align:right;">Filter the pinned suite before launching it</td></tr><tr><td style="text-align:right;">Keep editable analysis in a notebook</td><td style="text-align:right;"><a href="/PerfChecker/dev/interfaces/repl-pluto#Pluto-dashboard">Pluto</a></td><td style="text-align:right;">Download the notebook, choose a version set and save the result</td></tr><tr><td style="text-align:right;">Explore or export measured curves and profiles</td><td style="text-align:right;"><a href="./visualization">Makie</a></td><td style="text-align:right;">Inspect nine versions and download their measurements</td></tr><tr><td style="text-align:right;">Include saved measurements in my own documentation</td><td style="text-align:right;"><a href="./documentation">Documenter</a></td><td style="text-align:right;">Select the export observations from a saved suite bundle</td></tr></tbody></table><h2 id="What-to-have-ready" tabindex="-1">What to have ready <a class="header-anchor" href="#What-to-have-ready" aria-label="Permalink to &quot;What to have ready {#What-to-have-ready}&quot;">​</a></h2><p>For existing test items, prepare the package&#39;s test dependencies and load TestItemRunner with PerfChecker. The <a href="./../guide/first-check">first-result tutorial</a> provides a downloadable item if you need an example.</p><p>For the suite controls, start with a suite that identifies the workloads and versions to run. The <a href="./../tutorials/bibliography">Bibliography walkthrough</a> supplies this file and the launch commands for each interface. A <strong>plan</strong> selects what will execute; a <strong>saved result</strong> contains what already executed.</p><p>Plotting and Documenter examples require a saved <strong>suite run bundle</strong>. The <code>testitems.json</code> report from native test items is a different format; it cannot be passed to <code>read_run_bundle</code> or plotted by the suite plot API. Use the suite benchmark in the Bibliography walkthrough to obtain the plotting example.</p><h2 id="Which-package-supplies-each-interface?" tabindex="-1">Which package supplies each interface? <a class="header-anchor" href="#Which-package-supplies-each-interface?" aria-label="Permalink to &quot;Which package supplies each interface? {#Which-package-supplies-each-interface?}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Package</th><th style="text-align:right;">Capability</th></tr></thead><tbody><tr><td style="text-align:right;">PerfChecker</td><td style="text-align:right;">Julia API, command line and text REPL</td></tr><tr><td style="text-align:right;">PerfCheckerWeb</td><td style="text-align:right;">Oxygen Studio and HTTP endpoints</td></tr><tr><td style="text-align:right;">PerfCheckerPluto</td><td style="text-align:right;">Notebook controls and Pluto launch</td></tr><tr><td style="text-align:right;">PerfCheckerMakie</td><td style="text-align:right;">Makie figures; WGLMakie adds interactive HTML</td></tr></tbody></table><p>See <a href="./../guide/installation">installation</a> for what to add and current V1 availability. The interface packages&#39; first General registrations are pending. VS Code is an editor extension with a separate installation, described on its page.</p><p>Load the corresponding PerfChecker package to use an interface. If dependency versions conflict, put the interfaces in separate environments and open the same saved suite bundle in each.</p><p>The interfaces are ordinary Julia packages with their own UUIDs and versions. See <a href="/PerfChecker/dev/architecture-roadmap#Register-packages-from-the-shared-repository">package registration</a> for how they are registered from the shared repository.</p>',12)])])}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
